// Compute Precision@3 for this question
const item = $input.item.json;
const queryResponse = item;

// Get the batch context to find the original question + expected_keywords
const batchItems = $('Process One by One').all();
const currentBatch = batchItems[0];
const expectedKeywords = currentBatch.json.expected_keywords || [];

const answer = (queryResponse.answer || '').toLowerCase();
const sources = queryResponse.sources || [];

// Collect all text to search: answer + all source text_previews
const allText = [
  answer,
  ...sources.map(s => (s.metadata?.text_preview || '').toLowerCase())
].join(' ');

// Count how many expected keywords appear anywhere in answer+sources
const matchingKeywords = expectedKeywords.filter(kw =>
  allText.includes(kw.toLowerCase())
);

const precision = expectedKeywords.length > 0
  ? (matchingKeywords.length / expectedKeywords.length)
  : 0;

return [{
  json: {
    question: currentBatch.json.question,
    answer: queryResponse.answer,
    expected_keywords: expectedKeywords,
    matching_keywords: matchingKeywords,
    precision: parseFloat(precision.toFixed(4)),
    precision_pct: parseFloat((precision * 100).toFixed(2)),
    latency_ms: queryResponse.latency_ms || 0,
    token_count: queryResponse.token_count || 0,
    model_used: queryResponse.model_used || 'unknown',
    sources_count: sources.length,
    timestamp: new Date().toISOString()
  }
}];

// Calculate aggregate statistics across all 10 eval results
const results = $input.item.json.eval_results || [];

const totalQuestions = results.length;
const avgPrecision = totalQuestions > 0
  ? results.reduce((sum, r) => sum + (r.precision || 0), 0) / totalQuestions
  : 0;
const avgLatencyMs = totalQuestions > 0
  ? Math.round(results.reduce((sum, r) => sum + (r.latency_ms || 0), 0) / totalQuestions)
  : 0;
const avgTokens = totalQuestions > 0
  ? Math.round(results.reduce((sum, r) => sum + (r.token_count || 0), 0) / totalQuestions)
  : 0;
const PRECISION_THRESHOLD = 0.5;  // 50% keyword match = acceptable
const passCount = results.filter(r => (r.precision || 0) >= PRECISION_THRESHOLD).length;
const failCount = totalQuestions - passCount;

// Worst performing questions (for debugging)
const worstQuestions = [...results]
  .sort((a, b) => (a.precision || 0) - (b.precision || 0))
  .slice(0, 3)
  .map(r => `• _${r.question}_ (${(r.precision_pct || 0).toFixed(0)}%)`)
  .join('\n');

const isMonday = new Date().getDay() === 1;

return [{
  json: {
    eval_results: results,
    total_questions: totalQuestions,
    avg_precision: parseFloat(avgPrecision.toFixed(4)),
    avg_precision_pct: parseFloat((avgPrecision * 100).toFixed(2)),
    avg_latency_ms: avgLatencyMs,
    avg_tokens: avgTokens,
    pass_count: passCount,
    fail_count: failCount,
    worst_questions: worstQuestions,
    precision_threshold: PRECISION_THRESHOLD,
    is_monday: isMonday,
    evaluated_at: new Date().toISOString()
  }
}];

